from collections import Counter

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    if rows <= 0 or cols <= 0:
        return grid

    # Find separator row (where all cells are the same value)
    sep_row = None
    sep_col = None
    sep_val = 0

    for i in range(rows):
        if rows > 0 and any(grid[i][0] == 0):
            val = grid[i][0]
            if all(grid[i][j] == val for j in range(cols)):
                sep_row = i
                sep_val = val
                break

    for j in range(cols):
        if sep_row is not None and sep_col is None:
            val = grid[0][j] if j < cols else 0
            if all(grid[i][j] == val for i in range(rows)):
                sep_col = j
                sep_val = val
                break

    if sep_row is None or sep_col is None:
        return grid

    # Extract TL quadrant (rows before separator, cols before separator)
    tl = [row[:sep_col] for row in grid[:sep_row]]

    if not tl or not tl[0]:
        return grid

    # Count all colors in TL to find background (most common) and pattern
    all_vals = []
    for r in range(len(tl)):
        for c in range(len(tl[r])):
            all_vals.append(tl[r][c])

    counts = Counter(all_vals)
    # Background is most common color
    bg_color = counts.most_common(1)[0][0]

    # Output dimensions
    out_rows = len(tl)
    out_cols = len(tl[0])

    # Build output: background stays same, pattern becomes separator value
    result = []
    for r in range(out_rows):
        row = []
        for c in range(out_cols):
            val = tl[r][c]
            if val == bg_color:
                row.append(val)  # Background stays
            else:
                row.append(sep_val)  # Pattern becomes separator
        result.append(row)

    return result
